import 'package:flutter/material.dart';
import 'package:connectivity_plus/connectivity_plus.dart';

class ConnectivityCheckExample extends StatefulWidget {
  const ConnectivityCheckExample({super.key});

  @override
  State<ConnectivityCheckExample> createState() => _ConnectivityCheckExampleState();
}

class _ConnectivityCheckExampleState extends State<ConnectivityCheckExample> {
  List<ConnectivityResult> _connectionStatus = [ConnectivityResult.none];
  final Connectivity _connectivity = Connectivity();

  @override
  void initState() {
    super.initState();
    _checkConnectivity();
  }

  Future<void> _checkConnectivity() async {
    final result = await _connectivity.checkConnectivity();
    setState(() {
      _connectionStatus = result;
    });
  }

  String _getStatusText() {
    if (_connectionStatus.contains(ConnectivityResult.none)) {
      return '오프라인';
    }

    final types = <String>[];
    if (_connectionStatus.contains(ConnectivityResult.wifi)) {
      types.add('WiFi');
    }
    if (_connectionStatus.contains(ConnectivityResult.mobile)) {
      types.add('모바일 데이터');
    }
    if (_connectionStatus.contains(ConnectivityResult.ethernet)) {
      types.add('이더넷');
    }
    if (_connectionStatus.contains(ConnectivityResult.vpn)) {
      types.add('VPN');
    }
    if (_connectionStatus.contains(ConnectivityResult.bluetooth)) {
      types.add('블루투스');
    }
    if (_connectionStatus.contains(ConnectivityResult.other)) {
      types.add('기타');
    }

    return types.join(' + ');
  }

  IconData _getStatusIcon() {
    if (_connectionStatus.contains(ConnectivityResult.none)) {
      return Icons.signal_wifi_off;
    }
    if (_connectionStatus.contains(ConnectivityResult.wifi)) {
      return Icons.wifi;
    }
    if (_connectionStatus.contains(ConnectivityResult.mobile)) {
      return Icons.signal_cellular_alt;
    }
    return Icons.signal_wifi_statusbar_4_bar;
  }

  Color _getStatusColor() {
    if (_connectionStatus.contains(ConnectivityResult.none)) {
      return Colors.red;
    }
    return Colors.green;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('연결 상태')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(
              _getStatusIcon(),
              size: 100,
              color: _getStatusColor(),
            ),
            const SizedBox(height: 20),
            Text(
              _getStatusText(),
              style: TextStyle(
                fontSize: 24,
                fontWeight: FontWeight.bold,
                color: _getStatusColor(),
              ),
            ),
            const SizedBox(height: 40),
            ElevatedButton(
              onPressed: _checkConnectivity,
              child: const Text('다시 확인'),
            ),
          ],
        ),
      ),
    );
  }
}

import 'dart:async';
import 'package:flutter/material.dart';
import 'package:connectivity_plus/connectivity_plus.dart';

class ConnectivityStreamExample extends StatefulWidget {
  const ConnectivityStreamExample({super.key});

  @override
  State<ConnectivityStreamExample> createState() => _ConnectivityStreamExampleState();
}

class _ConnectivityStreamExampleState extends State<ConnectivityStreamExample> {
  final Connectivity _connectivity = Connectivity();
  late StreamSubscription<List<ConnectivityResult>> _subscription;
  List<ConnectivityResult> _connectionStatus = [];
  final List<String> _history = [];

  @override
  void initState() {
    super.initState();
    _initConnectivity();
    _subscribeToConnectivity();
  }

  Future<void> _initConnectivity() async {
    final result = await _connectivity.checkConnectivity();
    _updateStatus(result);
  }

  void _subscribeToConnectivity() {
    _subscription = _connectivity.onConnectivityChanged.listen(
      (result) {
        _updateStatus(result);
        _addToHistory(result);
      },
    );
  }

  void _updateStatus(List<ConnectivityResult> result) {
    setState(() {
      _connectionStatus = result;
    });
  }

  void _addToHistory(List<ConnectivityResult> result) {
    final time = DateTime.now().toString().substring(11, 19);
    final status = result.map((r) => r.name).join(', ');
    setState(() {
      _history.insert(0, '[$time] $status');
      if (_history.length > 10) _history.removeLast();
    });
  }

  @override
  void dispose() {
    _subscription.cancel();
    super.dispose();
  }

  bool get isOnline => !_connectionStatus.contains(ConnectivityResult.none) &&
      _connectionStatus.isNotEmpty;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('실시간 연결 감지'),
        actions: [
          Padding(
            padding: const EdgeInsets.all(8),
            child: Icon(
              isOnline ? Icons.cloud_done : Icons.cloud_off,
              color: isOnline ? Colors.green : Colors.red,
            ),
          ),
        ],
      ),
      body: Column(
        children: [
          // 현재 상태
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(16),
            color: isOnline ? Colors.green[100] : Colors.red[100],
            child: Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Icon(
                  isOnline ? Icons.wifi : Icons.wifi_off,
                  color: isOnline ? Colors.green : Colors.red,
                ),
                const SizedBox(width: 8),
                Text(
                  isOnline
                      ? '온라인 (${_connectionStatus.map((r) => r.name).join(", ")})'
                      : '오프라인',
                  style: TextStyle(
                    fontWeight: FontWeight.bold,
                    color: isOnline ? Colors.green[800] : Colors.red[800],
                  ),
                ),
              ],
            ),
          ),
          // 변경 기록
          Expanded(
            child: ListView.builder(
              itemCount: _history.length,
              itemBuilder: (context, index) {
                return ListTile(
                  leading: const Icon(Icons.history),
                  title: Text(_history[index]),
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

import 'dart:async';
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:flutter/foundation.dart';

class NetworkService {
  static final NetworkService _instance = NetworkService._internal();
  factory NetworkService() => _instance;
  NetworkService._internal();

  final Connectivity _connectivity = Connectivity();
  StreamSubscription<List<ConnectivityResult>>? _subscription;

  final _controller = StreamController<bool>.broadcast();
  Stream<bool> get onlineStream => _controller.stream;

  List<ConnectivityResult> _currentStatus = [];

  bool get isOnline =>
      _currentStatus.isNotEmpty &&
      !_currentStatus.contains(ConnectivityResult.none);

  bool get isWifi => _currentStatus.contains(ConnectivityResult.wifi);
  bool get isMobile => _currentStatus.contains(ConnectivityResult.mobile);

  Future<void> initialize() async {
    _currentStatus = await _connectivity.checkConnectivity();
    _subscription = _connectivity.onConnectivityChanged.listen(
      (result) {
        final wasOnline = isOnline;
        _currentStatus = result;
        final nowOnline = isOnline;

        if (wasOnline != nowOnline) {
          _controller.add(nowOnline);
          debugPrint('Network status changed: ${nowOnline ? "online" : "offline"}');
        }
      },
    );
  }

  Future<bool> checkConnection() async {
    _currentStatus = await _connectivity.checkConnectivity();
    return isOnline;
  }

  void dispose() {
    _subscription?.cancel();
    _controller.close();
  }
}

// Provider와 함께 사용
import 'package:flutter/material.dart';

class NetworkAwareWidget extends StatelessWidget {
  final Widget onlineChild;
  final Widget offlineChild;

  const NetworkAwareWidget({
    super.key,
    required this.onlineChild,
    required this.offlineChild,
  });

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<bool>(
      stream: NetworkService().onlineStream,
      initialData: NetworkService().isOnline,
      builder: (context, snapshot) {
        final isOnline = snapshot.data ?? false;
        return isOnline ? onlineChild : offlineChild;
      },
    );
  }
}

// 오프라인 배너
class OfflineBanner extends StatelessWidget {
  const OfflineBanner({super.key});

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<bool>(
      stream: NetworkService().onlineStream,
      initialData: NetworkService().isOnline,
      builder: (context, snapshot) {
        final isOnline = snapshot.data ?? true;

        if (isOnline) return const SizedBox.shrink();

        return Container(
          width: double.infinity,
          color: Colors.red,
          padding: const EdgeInsets.symmetric(vertical: 8),
          child: const Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Icon(Icons.wifi_off, color: Colors.white, size: 16),
              SizedBox(width: 8),
              Text(
                '오프라인 상태입니다',
                style: TextStyle(color: Colors.white),
              ),
            ],
          ),
        );
      },
    );
  }
}

