// 오프라인 지원 화면
class OfflineSupportScreen extends StatefulWidget {
  const OfflineSupportScreen({super.key});

  @override
  State<OfflineSupportScreen> createState() => _OfflineSupportScreenState();
}

class _OfflineSupportScreenState extends State<OfflineSupportScreen> {
  final _connectivity = Connectivity();
  bool _isOnline = true;
  List<String> _items = [];
  bool _isLoading = false;

  @override
  void initState() {
    super.initState();
    _checkAndLoad();
    _connectivity.onConnectivityChanged.listen((result) {
      final online = result.isNotEmpty &&
          !result.contains(ConnectivityResult.none);
      if (online != _isOnline) {
        setState(() => _isOnline = online);
        if (online && _items.isEmpty) {
          _loadData();
        }
      }
    });
  }

  Future<void> _checkAndLoad() async {
    final result = await _connectivity.checkConnectivity();
    _isOnline = result.isNotEmpty &&
        !result.contains(ConnectivityResult.none);

    if (_isOnline) {
      await _loadData();
    } else {
      // 캐시된 데이터 로드
      _loadCachedData();
    }
  }

  Future<void> _loadData() async {
    setState(() => _isLoading = true);
    try {
      // API 호출 시뮬레이션
      await Future.delayed(const Duration(seconds: 1));
      setState(() {
        _items = List.generate(10, (i) => '온라인 아이템 ${i + 1}');
      });
      // 캐시에 저장
      // await _saveToCache(_items);
    } catch (e) {
      _loadCachedData();
    } finally {
      setState(() => _isLoading = false);
    }
  }

  void _loadCachedData() {
    // 캐시에서 로드
    setState(() {
      _items = List.generate(5, (i) => '캐시된 아이템 ${i + 1}');
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('오프라인 지원'),
        actions: [
          Icon(
            _isOnline ? Icons.cloud_done : Icons.cloud_off,
            color: _isOnline ? Colors.green : Colors.grey,
          ),
          const SizedBox(width: 16),
        ],
      ),
      body: Column(
        children: [
          // 오프라인 배너
          if (!_isOnline)
            Container(
              width: double.infinity,
              color: Colors.orange,
              padding: const EdgeInsets.all(8),
              child: const Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Icon(Icons.info, color: Colors.white, size: 16),
                  SizedBox(width: 8),
                  Text(
                    '오프라인 모드 - 캐시된 데이터를 표시합니다',
                    style: TextStyle(color: Colors.white),
                  ),
                ],
              ),
            ),
          // 콘텐츠
          Expanded(
            child: _isLoading
                ? const Center(child: CircularProgressIndicator())
                : RefreshIndicator(
                    onRefresh: _isOnline ? _loadData : () async {},
                    child: ListView.builder(
                      itemCount: _items.length,
                      itemBuilder: (context, index) {
                        return ListTile(
                          leading: CircleAvatar(child: Text('${index + 1}')),
                          title: Text(_items[index]),
                          subtitle: Text(_isOnline ? '실시간' : '캐시'),
                        );
                      },
                    ),
                  ),
          ),
        ],
      ),
    );
  }
}
